<?php declare(strict_types=1);$c=$user['company_id'];sync_management($db,$user);$notifications=phase_rows($db,'SELECT n.*,p.name project_name FROM notifications n LEFT JOIN projects p ON p.id=n.project_id WHERE n.company_id=? ORDER BY n.is_read,n.created_at DESC LIMIT 100',[$c]);$approvals=phase_rows($db,'SELECT a.*,p.name project_name,u.name requester_name,ap.name approver_name FROM approvals a LEFT JOIN projects p ON p.id=a.project_id LEFT JOIN users u ON u.id=a.requested_by LEFT JOIN users ap ON ap.id=a.approver_id WHERE a.company_id=? ORDER BY FIELD(a.status,"pending","approved","rejected"),a.created_at DESC',[$c]);$audits=phase_rows($db,'SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.company_id=? ORDER BY a.created_at DESC LIMIT 200',[$c]);$metrics=phase_one($db,'SELECT (SELECT COUNT(*) FROM projects WHERE company_id=?) projects,(SELECT COALESCE(SUM(budget),0) FROM projects WHERE company_id=?) budget,(SELECT COALESCE(SUM(amount+tax),0) FROM expenses WHERE company_id=? AND status IN("approved","paid")) spent,(SELECT COUNT(*) FROM leads WHERE company_id=?) leads,(SELECT COUNT(*) FROM bookings WHERE company_id=? AND status="active") bookings,(SELECT COALESCE(SUM(final_price),0) FROM bookings WHERE company_id=? AND status="active") sales,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE company_id=?) collected,(SELECT COUNT(*) FROM notifications WHERE company_id=? AND is_read=0) alerts',array_fill(0,8,$c));$migrations=phase_rows($db,'SELECT * FROM schema_migrations ORDER BY applied_at',[]);function p56h(string $a,string $page):string{return '<input type="hidden" name="csrf" value="'.e($_SESSION['csrf']).'"><input type="hidden" name="phase56_action" value="'.e($a).'"><input type="hidden" name="return_page" value="'.e($page).'">';}?>
<section class="page-title"><div><span class="eyebrow">MANAGEMENT</span><h1><?=e(match($page){'management'=>'Executive dashboard','reports'=>'Reports & exports','notifications'=>'Notifications','approvals'=>'Approval centre','audit'=>'Audit history','system'=>'System readiness',default=>'Management'})?></h1><p class="muted">Company-wide visibility, control and production oversight.</p></div></section>
<?php if($page==='management'):?><section class="cards"><article class="card"><span>Projects</span><strong><?=(int)$metrics['projects']?></strong></article><article class="card"><span>Total budget</span><strong><?=inr($metrics['budget'])?></strong></article><article class="card"><span>Actual spend</span><strong><?=inr($metrics['spent'])?></strong></article><article class="card"><span>Unread alerts</span><strong><?=(int)$metrics['alerts']?></strong></article></section><section class="cards"><article class="card"><span>Total leads</span><strong><?=(int)$metrics['leads']?></strong></article><article class="card"><span>Bookings</span><strong><?=(int)$metrics['bookings']?></strong></article><article class="card"><span>Sales value</span><strong><?=inr($metrics['sales'])?></strong></article><article class="card"><span>Collections</span><strong><?=inr($metrics['collected'])?></strong></article></section><div class="ops-grid"><section class="panel"><div class="panel-head"><h2>Needs attention</h2></div><?php foreach(array_slice(array_filter($notifications,fn($n)=>!$n['is_read']),0,8) as $n):?><div class="alert"><b><?=e($n['title'])?></b><small><?=e($n['message'])?></small></div><?php endforeach;?></section><section class="panel"><div class="panel-head"><h2>Pending approvals</h2></div><?php foreach(array_slice(array_filter($approvals,fn($a)=>$a['status']==='pending'),0,8) as $a):?><div class="alert"><b><?=e($a['title'])?></b><small><?=e($a['project_name'])?> · <?=inr($a['amount'])?></small></div><?php endforeach;?></section></div>
<?php elseif($page==='reports'):?><div class="report-grid"><a href="/?business=construction&export=projects"><b>Project portfolio</b><small>Budget, status and construction progress</small><span>Download CSV</span></a><a href="/?business=construction&export=expenses"><b>Expense summary</b><small>Project, category, amount, tax and status</small><span>Download CSV</span></a><a href="/?business=construction&export=leads"><b>Lead performance</b><small>Source, pipeline status and assignment</small><span>Download CSV</span></a><a href="/?business=construction&export=collections"><b>Collections</b><small>Receivables, receipts and outstanding stages</small><span>Download CSV</span></a></div><section class="table-card"><table><thead><tr><th>Metric</th><th>Value</th></tr></thead><tbody><tr><td>Budget vs actual</td><td><?=inr($metrics['budget'])?> / <?=inr($metrics['spent'])?></td></tr><tr><td>Lead-to-booking conversion</td><td><?=(float)$metrics['leads']>0?round((float)$metrics['bookings']/(float)$metrics['leads']*100,1):0?>%</td></tr><tr><td>Sales collected</td><td><?=(float)$metrics['sales']>0?round((float)$metrics['collected']/(float)$metrics['sales']*100,1):0?>%</td></tr></tbody></table></section>
<?php elseif($page==='notifications'):?><section class="list-card"><?php foreach($notifications as $n):?><div class="notification-row <?=$n['is_read']?'read':''?>"><div><span class="pill"><?=e(str_replace('_',' ',$n['type']))?></span><b><?=e($n['title'])?></b><p><?=e($n['message'])?></p><small><?=e($n['project_name'])?> · <?=e($n['created_at'])?></small></div><?php if(!$n['is_read']):?><form method="post"><?=p56h('notification_read','notifications')?><input type="hidden" name="notification_id" value="<?=e($n['id'])?>"><button class="text-button">Mark read</button></form><?php endif;?></div><?php endforeach;?></section>
<?php elseif($page==='approvals'):?><?=phase_table(['Request','Project','Amount','Requested by','Status','Decision'],array_map(function($a){$decision=$a['status']==='pending'?'<form class="approval-form" method="post">'.p56h('approval_decide','approvals').'<input type="hidden" name="approval_id" value="'.e($a['id']).'"><input name="decision_notes" placeholder="Decision note"><button name="decision" value="approved">Approve</button><button class="danger" name="decision" value="rejected">Reject</button></form>':e($a['approver_name']?:'System');return[e($a['title']),e($a['project_name']),inr($a['amount']),e($a['requester_name']),'<span class="pill">'.e($a['status']).'</span>',$decision];},$approvals))?>
<?php elseif($page==='audit'):?><?=phase_table(['Time','User','Module','Action','Record','IP'],array_map(fn($a)=>[e($a['created_at']),e($a['user_name']?:'System'),e($a['module_name']),e($a['action_name']),e($a['record_id']),e($a['ip_address'])],$audits))?>
<?php else:?><section class="cards"><article class="card"><span>Application</span><strong>Healthy</strong><small class="muted">PHP session + MySQL</small></article><article class="card"><span>Database migrations</span><strong><?=count($migrations)?></strong><small class="muted">Tracked releases</small></article><article class="card"><span>HTTPS</span><strong><?=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'Active':'Check'?></strong><small class="muted">Secure cookies enabled</small></article><article class="card"><span>Environment</span><strong>Production</strong><small class="muted">Errors hidden from users</small></article></section><?=phase_table(['Migration','Description','Applied'],array_map(fn($m)=>[e($m['version']),e($m['description']),e($m['applied_at'])],$migrations))?><section class="form-card wide"><h2>Data safety</h2><p>Database backups and restore testing must be scheduled in Hostinger hPanel. Application credentials remain server-side and are excluded from source control.</p><p class="muted">Recommended: daily database backup, weekly restore verification, and a backup before every schema release.</p></section><?php endif;?>
